/*
 * The accessors live here rather than in hk_font.c so that the engine
 * never names a table: regenerating this file cannot break that one.
 */
const hk_face_t *hk_font_small(void) { return &small_face; }
const hk_face_t *hk_font_body(void) { return &body_face; }
const hk_face_t *hk_font_display(void) { return &display_face; }

